// One sheet row per question and engine, dated with the week.
const weekOf = $now.toFormat('yyyy-MM-dd');

return $input.all()
  .filter((item) => item.json.engine)
  .map(({ json: r }) => ({
    json: {
      'Week of': weekOf,
      Question: r.prompt,
      Engine: r.engine_name ?? r.engine,
      Status: r.status,
      Mentioned: r.brand_mentioned ? 'YES' : r.status === 'ok' ? 'no' : '',
      Rank: r.brand_rank ?? '',
      Cited: r.brand_cited ? 'YES' : r.status === 'ok' ? 'no' : '',
      'Competitors named': (r.competitors_mentioned ?? []).join(', '),
      'Share of voice': typeof r.share_of_voice === 'number' ? Math.round(r.share_of_voice * 100) + '%' : '',
      'Top sources': (r.top_cited_domains ?? []).slice(0, 5).join(', '),
    },
  }));

// One Slack message for the week: mention and citation rate per engine, and the competitors named most.
const settings = $('Set your brand and questions').first().json;
const rows = $input.all().map((item) => item.json).filter((r) => r.engine && r.status === 'ok');
const pct = (n, d) => (d ? Math.round((100 * n) / d) + '%' : 'n/a');

const engines = [...new Set(rows.map((r) => r.engine_name ?? r.engine))];
const lines = engines.map((name) => {
  const e = rows.filter((r) => (r.engine_name ?? r.engine) === name);
  const mentioned = e.filter((r) => r.brand_mentioned).length;
  const cited = e.filter((r) => r.brand_cited).length;
  return `• ${name}: named in ${mentioned} of ${e.length} answers (${pct(mentioned, e.length)}), site cited in ${cited}`;
});

const rivals = {};
for (const r of rows) for (const c of r.competitors_mentioned ?? []) rivals[c] = (rivals[c] ?? 0) + 1;
const top = Object.entries(rivals).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([c, n]) => `${c} (${n})`).join(', ');

const named = rows.filter((r) => r.brand_mentioned).length;
const text = [
  `*AI visibility for ${settings.brand}, week of ${$now.toFormat('yyyy-MM-dd')}*`,
  `Named in ${named} of ${rows.length} AI answers (${pct(named, rows.length)}).`,
  ...lines,
  top ? `Competitors named most: ${top}` : 'No tracked competitor was named.',
].join('\n');

return [{ json: { text, slackChannel: settings.slackChannel } }];
